class Solution:
    def maxScore(self, cardPoints: list[int], k: int) -> int:
        n = len(cardPoints)
        best = 0
        for left in range(k + 1):
            total = 0
            for i in range(left):
                total += cardPoints[i]
            for i in range(n - (k - left), n):
                total += cardPoints[i]
            best = max(best, total)
        return best

solutions.better:
class Solution:
    def maxScore(self, cardPoints: list[int], k: int) -> int:
        front = [0]
        for x in cardPoints:
            front.append(front[-1] + x)
        back = [0]
        for x in reversed(cardPoints):
            back.append(back[-1] + x)
        best = 0
        for left in range(k + 1):
            best = max(best, front[left] + back[k - left])
        return best

solutions.optimal:
class Solution:
    def maxScore(self, cardPoints: list[int], k: int) -> int:
        n = len(cardPoints)
        total = sum(cardPoints)
        keep = n - k
        if keep == 0:
            return total
        window = sum(cardPoints[:keep])
        min_keep = window
        for i in range(keep, n):
            window += cardPoints[i] - cardPoints[i - keep]
            min_keep = min(min_keep, window)
        return total - min_keep

